SELECT `__typedhouse_input`.`entityId`, `__typedhouse_input`.`at`, `__typedhouse_input`.`version`, `__typedhouse_input`.`stock` FROM (SELECT `c`.`entityId` AS `entityId`, `a`.`effectiveAt` AS `at`, `a`.`version` AS `version`, `a`.`market_stock_total` AS `stock` FROM (SELECT `entityId` FROM `entity_ots_component` WHERE `tenantId` = {p0:String} AND startsWith(`category`, {p1:String})) AS `c` INNER ALL JOIN (SELECT `entityId`, `version`, `effectiveAt`, `market_stock_total` FROM `metric_group_ots_component_market_availability` FINAL WHERE `tenantId` = {p2:String} AND ((`effectiveAt`) BETWEEN (CAST({p3:DateTime64(3, 'UTC')} AS DateTime64(3))) AND (CAST({p4:DateTime64(3, 'UTC')} AS DateTime64(3))))) AS `a` ON `c`.`entityId` = `a`.`entityId`) AS `__typedhouse_input` ORDER BY `__typedhouse_input`.`entityId` ASC, `__typedhouse_input`.`at` ASC, `__typedhouse_input`.`version` ASC
